/* ==========================================================================
   Rollout Board Game Cafe - Design System
   ========================================================================== */

:root {
  --color-white: #F7F9FC;     /* Game Night White */
  --color-blueberry: #3B6FE8; /* Rollout Blueberry */
  --color-mint: #3ECFB2;      /* Playmat Mint */
  --color-coral: #FF6B5B;     /* Dice Coral */
  --color-yellow: #FFD23F;    /* Sun Token Yellow */
  --color-plum: #2D2250;      /* Velvet Plum */
  --color-plum-darker: #1E1740;
  --color-gray: #6B7A99;      /* Felt Gray */
  --color-chalk: #EDF0F7;     /* Cloud Chalk */

  --font-heading: 'Nunito', system-ui, -apple-system, sans-serif;
  --font-body: 'DM Sans', system-ui, -apple-system, sans-serif;
  --font-accent: 'Fredoka One', 'Nunito', system-ui, sans-serif;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 999px;

  --container: 1200px;
  --container-narrow: 960px;
}

/* Reset & base */
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  color: var(--color-gray);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--color-plum);
  margin: 0;
  line-height: 1.15;
  letter-spacing: -0.01em;
  font-weight: 800;
}

p { margin: 0; }

/* Layout helpers */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding-left: 32px;
  padding-right: 32px;
}
.container-narrow {
  width: 100%;
  max-width: var(--container-narrow);
  margin: 0 auto;
  padding-left: 32px;
  padding-right: 32px;
}

/* Eyebrow / accent labels */
.eyebrow {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--color-blueberry);
  display: inline-block;
}
.eyebrow.is-mint { color: var(--color-mint); }
.eyebrow.is-coral { color: var(--color-coral); }
.eyebrow.is-yellow { color: var(--color-yellow); }
.eyebrow.is-plum { color: var(--color-plum); }
.eyebrow.is-plum-soft { color: rgba(45, 34, 80, 0.7); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-pill);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 16px;
  line-height: 1;
  transition: transform 0.15s ease, background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
  cursor: pointer;
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary {
  background: var(--color-blueberry);
  color: var(--color-white);
}
.btn-primary:hover { background: #2c5dd8; }

.btn-secondary {
  background: transparent;
  color: var(--color-white);
  border-color: var(--color-white);
}
.btn-secondary:hover {
  background: var(--color-coral);
  border-color: var(--color-coral);
  color: var(--color-white);
}
.btn-mint {
  background: var(--color-mint);
  color: var(--color-plum);
}
.btn-mint:hover { background: #34b89d; }
.btn-plum {
  background: var(--color-plum);
  color: var(--color-white);
}
.btn-plum:hover { background: #1f1739; }
.btn-white {
  background: var(--color-white);
  color: var(--color-blueberry);
}
.btn-white:hover { background: var(--color-yellow); color: var(--color-plum); }
.btn-outline-blue {
  background: transparent;
  color: var(--color-blueberry);
  border-color: var(--color-blueberry);
}
.btn-outline-blue:hover { background: var(--color-blueberry); color: var(--color-white); }
.btn-outline-white {
  background: transparent;
  color: var(--color-white);
  border-color: var(--color-white);
}
.btn-outline-white:hover { background: var(--color-white); color: var(--color-blueberry); }

/* Site Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--color-plum);
  color: var(--color-white);
}
.site-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 32px;
  max-width: 1280px;
  margin: 0 auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 22px;
  color: var(--color-white);
  letter-spacing: -0.01em;
}
.brand-mark {
  width: 36px;
  height: 36px;
  flex: none;
}
.site-nav {
  display: flex;
  gap: 8px;
  align-items: center;
}
.site-nav a {
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14.5px;
  color: rgba(247, 249, 252, 0.78);
  transition: background 0.18s ease, color 0.18s ease;
}
.site-nav a:hover { color: var(--color-white); background: rgba(247, 249, 252, 0.08); }
.site-nav a.is-active {
  color: var(--color-white);
  background: var(--color-blueberry);
}
.site-nav-cta {
  margin-left: 8px;
  padding: 10px 18px;
  border-radius: var(--radius-pill);
  background: var(--color-mint);
  color: var(--color-plum);
  font-weight: 700;
  font-size: 14px;
}
.site-nav-cta:hover { background: var(--color-yellow); }

.nav-toggle {
  display: none;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: rgba(247, 249, 252, 0.08);
  color: var(--color-white);
  align-items: center;
  justify-content: center;
}

/* Footer */
.site-footer {
  background: var(--color-plum);
  color: rgba(247, 249, 252, 0.75);
  padding: 64px 0 32px;
}
.site-footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 40px;
}
.site-footer h4 {
  font-size: 14px;
  font-family: var(--font-accent);
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--color-mint);
  margin-bottom: 16px;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; }
.site-footer li { margin-bottom: 10px; font-size: 15px; }
.site-footer a:hover { color: var(--color-white); }
.site-footer-tagline {
  margin-top: 12px;
  font-size: 15px;
  max-width: 320px;
  line-height: 1.6;
}
.site-footer-bottom {
  margin-top: 48px;
  border-top: 1px solid rgba(247, 249, 252, 0.10);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 13px;
  color: rgba(247, 249, 252, 0.55);
}

/* ==========================================================================
   Sections - shared
   ========================================================================== */
section { position: relative; }

/* ==========================================================================
   HOME PAGE
   ========================================================================== */

/* Hero */
.home-hero {
  display: grid;
  grid-template-columns: 45% 55%;
  min-height: 640px;
  background: var(--color-white);
}
.home-hero-text {
  background: var(--color-plum);
  padding: 100px 80px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.home-hero-text .eyebrow { color: var(--color-mint); margin-bottom: 18px; }
.home-hero-text h1 {
  font-size: clamp(42px, 5.2vw, 60px);
  color: var(--color-white);
  line-height: 1.08;
  letter-spacing: -0.02em;
  max-width: 480px;
  margin-bottom: 22px;
}
.home-hero-text .lede {
  color: rgba(247, 249, 252, 0.78);
  font-size: 18px;
  max-width: 400px;
  line-height: 1.6;
  margin-bottom: 36px;
}
.hero-ctas { display: flex; gap: 14px; flex-wrap: wrap; }
.hero-blob {
  position: absolute;
  bottom: -60px;
  left: -40px;
  width: 240px;
  height: 160px;
  background: var(--color-mint);
  border-radius: 80px 30px 60px 50px;
  transform: rotate(-15deg);
  opacity: 0.85;
}
.home-hero-art {
  background: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  position: relative;
}
.home-hero-art svg { width: 100%; height: auto; max-width: 720px; }

/* Stats Marquee */
.home-stats {
  background: var(--color-chalk);
  padding: 80px 0 100px;
  border-top: 1px solid var(--color-mint);
  border-bottom: 1px solid var(--color-mint);
}
.home-stats-header { text-align: center; max-width: 720px; margin: 0 auto 48px; padding: 0 32px; }
.home-stats-header .eyebrow { color: var(--color-coral); margin-bottom: 14px; }
.home-stats-header h2 { font-size: clamp(28px, 4vw, 38px); }
.stats-marquee {
  display: flex;
  gap: 80px;
  align-items: flex-start;
  overflow: hidden;
  padding: 0 24px;
  white-space: nowrap;
}
.stat-item { flex: 1 0 auto; text-align: center; }
.stat-value {
  font-family: var(--font-accent);
  font-size: clamp(64px, 9vw, 108px);
  color: var(--color-blueberry);
  line-height: 1;
  letter-spacing: -0.02em;
}
.stat-value .star { color: var(--color-yellow); }
.stat-desc {
  font-size: 15px;
  color: var(--color-gray);
  max-width: 200px;
  margin: 16px auto 0;
  line-height: 1.5;
  white-space: normal;
}

/* Feature Grid (asymmetric) */
.home-features { background: var(--color-white); padding: 100px 0; }
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 72px;
}
.section-header h2 {
  font-size: clamp(30px, 4vw, 40px);
  margin-top: 12px;
}
.section-header .lede {
  color: var(--color-gray);
  font-size: 17px;
  margin-top: 14px;
  max-width: 540px;
  margin-left: auto;
  margin-right: auto;
}
.feature-rows { display: flex; flex-direction: column; gap: 32px; }
.feature-row { display: grid; gap: 24px; }
.feature-row-1 { grid-template-columns: 7fr 5fr; }
.feature-row-2 { grid-template-columns: 5fr 7fr; }
.feature-card {
  background: var(--color-chalk);
  border-radius: var(--radius-lg);
  padding: 40px;
  display: flex;
