  line-height: 1.5;
}
.chart-card {
  background: var(--color-white);
  border-radius: var(--radius-md);
  padding: 24px 28px;
  border: 1px solid rgba(59, 111, 232, 0.30);
}
.chart-card h4 {
  font-family: var(--font-heading);
  font-size: 16px;
  font-weight: 700;
  color: var(--color-plum);
  margin-bottom: 18px;
}
.bar-chart { display: flex; flex-direction: column; gap: 14px; }
.bar-row { display: grid; grid-template-columns: 70px 1fr 70px; align-items: center; gap: 16px; }
.bar-label { font-size: 13px; color: var(--color-gray); }
.bar-track { background: var(--color-chalk); height: 14px; border-radius: 7px; overflow: hidden; }
.bar-fill { height: 100%; border-radius: 7px; }
.bar-fill-blue { background: var(--color-blueberry); }
.bar-fill-mint { background: var(--color-mint); }
.bar-value { font-size: 13px; font-weight: 600; color: var(--color-plum); text-align: right; }

/* Articles */
.community-articles {
  background: var(--color-white);
  padding: 80px 0;
}
.community-articles .section-header { text-align: left; max-width: 640px; margin: 0 0 40px; }
.community-articles .section-header .eyebrow { color: var(--color-coral); }
.community-articles h2 { font-size: clamp(26px, 4vw, 38px); }
.article-list { display: flex; flex-direction: column; }
.article-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 32px;
  align-items: center;
  padding: 28px 0;
  border-top: 1px solid var(--color-chalk);
  transition: background 0.18s ease;
}
.article-row:last-child { border-bottom: 1px solid var(--color-chalk); }
.article-row:hover { background: var(--color-chalk); padding-left: 12px; padding-right: 12px; border-radius: var(--radius-md); }
.article-row:hover h3 { color: var(--color-blueberry); }
.article-row:hover .arrow { transform: translateX(4px); }
.article-cat {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  padding: 5px 11px;
  border-radius: var(--radius-pill);
  display: inline-block;
}
.cat-recap { background: var(--color-coral); color: var(--color-white); }
.cat-guide { background: var(--color-blueberry); color: var(--color-white); }
.cat-story { background: var(--color-mint); color: var(--color-plum); }
.cat-spotlight { background: var(--color-yellow); color: var(--color-plum); }
.article-row h3 {
  font-size: 22px;
  font-weight: 700;
  color: var(--color-plum);
  margin-top: 10px;
  transition: color 0.18s ease;
}
.article-row p {
  font-size: 15px;
  color: var(--color-gray);
  margin-top: 6px;
  max-width: 64ch;
}
.article-author {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-gray);
}
.article-author .arrow {
  width: 18px;
  height: 18px;
  color: var(--color-blueberry);
  transition: transform 0.18s ease;
}

/* Community CTA Close */
.community-cta {
  background: var(--color-mint);
  padding: 96px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.community-cta-deco {
  position: absolute;
  pointer-events: none;
  opacity: 0.20;
  color: var(--color-white);
}
.deco-1 { top: 40px; left: 60px; width: 48px; }
.deco-2 { top: 60px; right: 80px; width: 48px; }
.deco-3 { bottom: 40px; right: 30%; width: 48px; }
.community-cta .eyebrow { color: rgba(45, 34, 80, 0.7); margin-bottom: 14px; }
.community-cta h2 {
  font-size: clamp(30px, 4.5vw, 42px);
  color: var(--color-plum);
  max-width: 700px;
  margin: 0 auto;
}
.community-cta .lede {
  color: rgba(45, 34, 80, 0.78);
  font-size: 17px;
  max-width: 56ch;
  margin: 16px auto 40px;
}
.community-cta .hero-ctas { justify-content: center; }

/* ==========================================================================
   BUY PAGE
   ========================================================================== */

/* Page Header */
.buy-header {
  background: var(--color-plum);
  padding: 96px 0 80px;
  text-align: center;
  color: var(--color-white);
}
.buy-header .eyebrow { color: var(--color-mint); }
.buy-header h1 {
  font-family: var(--font-accent);
  font-weight: 400;
  font-size: clamp(40px, 6.5vw, 76px);
  color: var(--color-white);
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-top: 12px;
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}
.buy-header .lede {
  color: rgba(247, 249, 252, 0.78);
  font-size: 18px;
  max-width: 600px;
  margin: 16px auto 40px;
}
.path-badges {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 20px;
}
.path-badge {
  width: 200px;
  border-radius: 24px;
  padding: 18px 16px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
}
.path-badge svg { width: 38px; height: 38px; }
.path-badge .label {
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 0.06em;
}
.badge-mint { background: var(--color-mint); color: var(--color-plum); }
.badge-yellow { background: var(--color-yellow); color: var(--color-plum); }
.badge-coral { background: var(--color-coral); color: var(--color-white); }

/* Pricing */
.buy-pricing {
  background: var(--color-white);
  padding: 80px 0;
}
.buy-pricing .section-intro { margin-bottom: 40px; }
.buy-pricing .section-intro .eyebrow { color: var(--color-blueberry); }
.buy-pricing h2 {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 700;
  margin-top: 8px;
}
.buy-pricing .lede {
  color: var(--color-gray);
  font-size: 17px;
  margin-top: 8px;
}
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.pricing-card {
  background: var(--color-chalk);
  border-radius: var(--radius-md);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
}
.pricing-card.is-premium { border-left: 2px solid var(--color-blueberry); }
.popular-badge {
  position: absolute;
  top: 14px;
  right: 14px;
  background: var(--color-mint);
  color: var(--color-plum);
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.06em;
  padding: 6px 14px;
  border-radius: 8px;
}
.pricing-card h3 {
  font-size: 22px;
  font-weight: 700;
  color: var(--color-plum);
}
.pricing-price {
  font-family: var(--font-heading);
  font-weight: 800;
  color: var(--color-blueberry);
  font-size: 30px;
  line-height: 1;
}
.pricing-card.is-premium .pricing-price { font-size: 34px; }
.pricing-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.pricing-meta .meta-pill {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 13px;
  background: var(--color-white);
  color: var(--color-gray);
  padding: 5px 11px;
  border-radius: 8px;
}
.pricing-card p {
  font-size: 16px;
  color: var(--color-gray);
  line-height: 1.6;
}
.buy-pricing .center-cta {
  text-align: center;
  margin-top: 32px;
}

/* Game Shop */
.buy-shop {
  background: var(--color-chalk);
  padding: 80px 0;
}
.shop-header {
  display: grid;
  grid-template-columns: 38% 1fr;
  gap: 4%;
  margin-bottom: 40px;
  align-items: center;
}
.shop-mockup {
  border-radius: 0 16px 16px 0;
  overflow: hidden;
  height: 320px;
  margin-left: -32px;
}
.shop-mockup svg { width: 100%; height: 100%; object-fit: cover; }
.shop-text .eyebrow { color: var(--color-coral); }
.shop-text h2 { font-size: clamp(28px, 4vw, 42px); font-weight: 700; margin-top: 8px; }
.shop-text p { font-size: 17px; margin-top: 10px; max-width: 520px; }
.shop-text .btn { margin-top: 24px; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--color-white);
  border-radius: 14px;
  padding: 20px;
  position: relative;
  display: flex;
  flex-direction: column;
}
.product-price {
  position: absolute;
  top: 12px;
  right: 12px;
  background: var(--color-coral);
  color: var(--color-white);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 15px;
  padding: 6px 12px;
  border-radius: 6px;
}
.product-card h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-plum);
  padding-right: 64px;
}
.product-avail {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 13px;
  color: var(--color-mint);
  margin-top: 6px;
}
.product-card p {
  font-size: 15px;
  color: var(--color-gray);
  margin-top: 10px;
  line-height: 1.6;
}
.product-stars { color: var(--color-yellow); margin-top: 12px; font-size: 14px; letter-spacing: 2px; }
.product-cta {
  margin-top: auto;
  padding-top: 14px;
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--color-blueberry);
}

/* Events Tickets */
.buy-events {
  background: var(--color-blueberry);
  padding: 80px 0;
  color: var(--color-white);
}
.buy-events .eyebrow { color: var(--color-yellow); }
.buy-events h2 {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 700;
  color: var(--color-white);
  margin-top: 8px;
}
.buy-events .lede {
  color: rgba(247, 249, 252, 0.85);
  font-size: 17px;
  margin-top: 8px;
  margin-bottom: 40px;
}
.tickets-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}
.ticket-card {
  background: rgba(237, 240, 247, 0.12);
  backdrop-filter: blur(4px);
  border: 1px solid rgba(247, 249, 252, 0.2);
  border-radius: var(--radius-md);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.ticket-tag {
  display: inline-block;
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.06em;
  padding: 4px 11px;
  border-radius: var(--radius-pill);
  align-self: flex-start;
}
.tag-tournament { background: var(--color-coral); color: var(--color-white); }
.tag-free { background: var(--color-mint); color: var(--color-plum); }
.tag-paid { background: var(--color-yellow); color: var(--color-plum); }
.ticket-card h3 {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-white);
}
.ticket-date {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 14px;
  color: var(--color-yellow);
}
.ticket-card p {
  font-size: 15px;
  color: rgba(247, 249, 252, 0.88);
  line-height: 1.6;
}
.ticket-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-top: 4px;
  gap: 12px;
}
.ticket-price {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 18px;
  color: var(--color-white);
}
.ticket-spots {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 14px;
  color: var(--color-yellow);
}
.ticket-spots.is-open { color: var(--color-mint); }
.ticket-card .btn-white {
  align-self: flex-start;
  padding: 10px 20px;
  font-size: 14px;
}
.buy-events .center-cta {
  text-align: center;
  margin-top: 32px;
}

/* Contact */
.buy-contact {
  background: var(--color-white);
  padding: 80px 0;
}
.contact-grid {
  display: grid;
  grid-template-columns: 32% 1fr;
  gap: 4%;
  align-items: stretch;
}
.contact-panel {
  background: var(--color-plum);
  border-radius: var(--radius-md);
  padding: 32px;
  color: var(--color-white);
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.contact-panel .eyebrow { color: var(--color-mint); margin-bottom: 12px; }
.contact-panel h2 {
  color: var(--color-white);
  font-size: clamp(24px, 3.5vw, 34px);
  font-weight: 700;
  line-height: 1.2;
}
.contact-panel hr {
  border: 0;
  height: 2px;
  width: 40px;
  background: var(--color-mint);
  margin: 20px 0;
}
.contact-panel p {
  color: rgba(247, 249, 252, 0.78);
  font-size: 15px;
  line-height: 1.65;
}
.contact-rows { display: flex; flex-direction: column; }
.contact-row {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 20px;
  padding: 20px 0;
  border-top: 1px solid var(--color-chalk);
  align-items: flex-start;
}
.contact-row:first-child { border-top: 0; }
.contact-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(62, 207, 178, 0.20);
  color: var(--color-mint);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.contact-row h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-plum);
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.contact-row p {
  font-size: 15px;
  color: var(--color-gray);
  margin-top: 6px;
}
.never-expires {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.06em;
  background: var(--color-yellow);
  color: var(--color-plum);
  padding: 4px 10px;
  border-radius: 10px;
}
.contact-cta { margin-top: 24px; }

/* ==========================================================================
   Responsive
   ========================================================================== */
@media (max-width: 980px) {
  .home-hero { grid-template-columns: 1fr; }
  .home-hero-text { padding: 64px 32px; }
  .home-hero-art { padding: 24px; }
  .feature-row-1, .feature-row-2 { grid-template-columns: 1fr 1fr; }
  .testimonial-row { grid-template-columns: 1fr; }
  .games-header-grid { grid-template-columns: 1fr; }
  .games-header-art { justify-content: center; order: -1; }
  .genre-grid { grid-template-columns: repeat(2, 1fr); }
  .picks-grid { grid-template-columns: repeat(2, 1fr); }
  .games-guides-grid { grid-template-columns: 1fr; }
  .guide-art { order: -1; }
  .faq-grid { grid-template-columns: 1fr; }
  .faq-cta-card { position: relative; top: auto; }
  .trailer-header-grid { grid-template-columns: 1fr; }
  .trailer-header-art { order: -1; justify-content: center; }
  .gallery-grid { grid-template-columns: repeat(2, 1fr); }
  .gallery-grid-bottom { grid-template-columns: 1fr; max-width: 100%; }
  .gallery-card.is-tilted { transform: none; }
  .timeline::before { left: 24px; }
  .timeline-item { grid-template-columns: 40px 1fr; }
  .timeline-item:nth-child(odd) .timeline-content:first-child,
  .timeline-item:nth-child(even) .timeline-content:last-child { display: none; }
  .timeline-marker { margin-left: 0; }
  .community-header-grid { grid-template-columns: 1fr; }
  .community-header-art { order: -1; }
  .events-grid { grid-template-columns: repeat(2, 1fr); }
  .giant-stats { grid-template-columns: repeat(2, 1fr); }
  .article-row { grid-template-columns: 1fr; gap: 12px; }
  .pricing-grid { grid-template-columns: 1fr; }
  .shop-header { grid-template-columns: 1fr; }
  .shop-mockup { margin-left: 0; border-radius: 16px; height: 220px; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .tickets-grid { grid-template-columns: 1fr; }
  .contact-grid { grid-template-columns: 1fr; }
  .site-footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 640px) {
  .container, .container-narrow { padding-left: 20px; padding-right: 20px; }
  .site-header-inner { padding: 12px 16px; }
  .site-nav { display: none; }
  .nav-toggle { display: inline-flex; }
  .site-nav.is-open {
    display: flex;
    position: absolute;
    top: 100%;
    left: 0; right: 0;
    background: var(--color-plum);
    flex-direction: column;
    padding: 12px;
    gap: 4px;
    border-top: 1px solid rgba(255,255,255,0.1);
  }
  .home-hero-text { padding: 48px 24px; }
  .home-hero-text h1 { font-size: 36px; }
  .home-stats { padding: 56px 0 64px; }
  .stats-marquee { gap: 56px; flex-wrap: wrap; justify-content: center; }
  .home-features, .home-testimonials, .home-cta { padding: 64px 0; }
  .feature-row-1, .feature-row-2 { grid-template-columns: 1fr; }
  .feature-card { padding: 28px; }
  .testimonial-card { padding: 28px; }
  .home-cta { padding: 80px 0; }
  .games-header { padding: 48px 0; }
  .genre-grid { grid-template-columns: 1fr; }
  .picks-grid { grid-template-columns: 1fr; }
  .events-grid { grid-template-columns: 1fr; }
  .giant-stats { grid-template-columns: 1fr; gap: 24px; }
  .giant-stat:nth-child(2), .giant-stat:nth-child(4) { transform: none; }
  .products-grid { grid-template-columns: 1fr; }
  .gallery-grid { grid-template-columns: 1fr; }
  .site-footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .site-footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
  .home-cta-icon { width: 56px; height: 56px; }
  .path-badge { width: 140px; padding: 14px 10px; }
  .buy-header h1 { font-size: 40px; }
}

