/* ==========================================================================
   Rollout Board Game Cafe - Design System
   ========================================================================== */

:root {
  --color-white: #F7F9FC;     /* Game Night White */
  --color-blueberry: #3B6FE8; /* Rollout Blueberry */
  --color-mint: #3ECFB2;      /* Playmat Mint */
  --color-coral: #FF6B5B;     /* Dice Coral */
  --color-yellow: #FFD23F;    /* Sun Token Yellow */
  --color-plum: #2D2250;      /* Velvet Plum */
  --color-plum-darker: #1E1740;
  --color-gray: #6B7A99;      /* Felt Gray */
  --color-chalk: #EDF0F7;     /* Cloud Chalk */

  --font-heading: 'Nunito', system-ui, -apple-system, sans-serif;
  --font-body: 'DM Sans', system-ui, -apple-system, sans-serif;
  --font-accent: 'Fredoka One', 'Nunito', system-ui, sans-serif;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 999px;

  --container: 1200px;
  --container-narrow: 960px;
}

/* Reset & base */
*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  color: var(--color-gray);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--color-plum);
  margin: 0;
  line-height: 1.15;
  letter-spacing: -0.01em;
  font-weight: 800;
}

p { margin: 0; }

/* Layout helpers */
.container {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  padding-left: 32px;
  padding-right: 32px;
}
.container-narrow {
  width: 100%;
  max-width: var(--container-narrow);
  margin: 0 auto;
  padding-left: 32px;
  padding-right: 32px;
}

/* Eyebrow / accent labels */
.eyebrow {
  font-family: var(--font-accent);
  font-size: 12px;
  letter-spacing: 0.10em;
  text-transform: uppercase;
  color: var(--color-blueberry);
  display: inline-block;
}
.eyebrow.is-mint { color: var(--color-mint); }
.eyebrow.is-coral { color: var(--color-coral); }
.eyebrow.is-yellow { color: var(--color-yellow); }
.eyebrow.is-plum { color: var(--color-plum); }
.eyebrow.is-plum-soft { color: rgba(45, 34, 80, 0.7); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-pill);
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 16px;
  line-height: 1;
  transition: transform 0.15s ease, background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
  cursor: pointer;
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary {
  background: var(--color-blueberry);
  color: var(--color-white);
}
.btn-primary:hover { background: #2c5dd8; }

.btn-secondary {
  background: transparent;
  color: var(--color-white);
  border-color: var(--color-white);
}
.btn-secondary:hover {
  background: var(--color-coral);
  border-color: var(--color-coral);
  color: var(--color-white);
}
.btn-mint {
